/** @category Validation Rules */

import { inspect } from '../../jsutils/inspect.ts';
import type { Maybe } from '../../jsutils/Maybe.ts';

import { GraphQLError } from '../../error/GraphQLError.ts';

import type {
  ArgumentNode,
  DirectiveNode,
  FieldNode,
  FragmentArgumentNode,
  FragmentDefinitionNode,
  FragmentSpreadNode,
  SelectionSetNode,
  ValueNode,
} from '../../language/ast.ts';
import { Kind } from '../../language/kinds.ts';
import { print } from '../../language/printer.ts';
import type { ASTVisitor } from '../../language/visitor.ts';

import type {
  GraphQLField,
  GraphQLNamedType,
  GraphQLOutputType,
} from '../../type/definition.ts';
import {
  getNamedType,
  isInterfaceType,
  isLeafType,
  isListType,
  isNonNullType,
  isObjectType,
} from '../../type/definition.ts';

import { sortValueNode } from '../../utilities/sortValueNode.ts';
import { typeFromAST } from '../../utilities/typeFromAST.ts';

import type { ValidationContext } from '../ValidationContext.ts';

/* eslint-disable max-params */
// This file contains a lot of such errors but we plan to refactor it anyway
// so just disable it for entire file.

function reasonMessage(reason: ConflictReasonMessage): string {
  if (Array.isArray(reason)) {
    return reason
      .map(
        ({ responseName, reason: subReason }) =>
          `subfields "${responseName}" conflict because ` +
          reasonMessage(subReason),
      )
      .join(' and ');
  }
  return reason;
}

/**
 * Overlapping fields can be merged
 *
 * A selection set is only valid if all fields (including spreading any
 * fragments) either correspond to distinct response names or can be merged
 * without ambiguity.
 *
 * See https://spec.graphql.org/draft/#sec-Field-Selection-Merging
 * @param validationContext - The validation context used while checking the document.
 * @returns A visitor that reports validation errors for this rule.
 * @example
 * ```ts
 * import { buildSchema, parse, validate } from 'graphql';
 * import { OverlappingFieldsCanBeMergedRule } from 'graphql/validation';
 *
 * const schema = buildSchema(`
 *   type Query {
 *     dog: Dog
 *   }
 *
 *   type Dog {
 *     name: String
 *     barkVolume: Int
 *   }
 * `);
 *
 * const invalidDocument = parse(`
 *   { dog { value: barkVolume value: name } }
 * `);
 * const invalidErrors = validate(schema, invalidDocument, [
 *   OverlappingFieldsCanBeMergedRule,
 * ]);
 *
 * invalidErrors.length; // => 1
 *
 * const validDocument = parse(`
 *   { dog { barkVolume name } }
 * `);
 * const validErrors = validate(schema, validDocument, [
 *   OverlappingFieldsCanBeMergedRule,
 * ]);
 *
 * validErrors; // => []
 * ```
 */
export function OverlappingFieldsCanBeMergedRule(
  validationContext: ValidationContext,
): ASTVisitor {
  const ruleContext: RuleContext = {
    // A memoization for when fields and a fragment or two fragments are compared
    // "between" each other for conflicts. Comparisons may be made many times,
    // so memoizing this can dramatically improve the performance of this validator.
    comparedFieldsAndFragmentPairs: new OrderedPairSet(),
    comparedFragmentPairs: new PairSet(),

    // A cache for the "field map" and list of fragment spreads found in any given
    // selection set.
    cachedCollectFieldsResults: new Map(),
  };
  let fragmentVarMap: VariableMap | undefined;

  return {
    FragmentDefinition: {
      enter(node) {
        const fragmentName = node.name.value;
        const fragmentSignature =
          validationContext.getFragmentSignatureByName()(fragmentName);
        fragmentVarMap = getVarMap(fragmentSignature, fragmentName);
      },
      leave() {
        fragmentVarMap = undefined;
      },
    },
    SelectionSet(selectionSet) {
      const conflicts = findConflictsWithinSelectionSet(
        validationContext,
        ruleContext,
        validationContext.getParentType(),
        selectionSet,
        fragmentVarMap,
      );
      for (const { responseName, reason, fields1, fields2 } of conflicts) {
        const reasonMsg = reasonMessage(reason);
        validationContext.reportError(
          new GraphQLError(
            `Fields "${responseName}" conflict because ${reasonMsg}. Use different aliases on the fields to fetch both if this was intentional.`,
            { nodes: fields1.concat(fields2) },
          ),
        );
      }
    },
  };
}

interface Conflict extends ConflictReason {
  fields1: Array<FieldNode>;
  fields2: Array<FieldNode>;
}
// Field name and reason.
interface ConflictReason {
  responseName: string;
  reason: ConflictReasonMessage;
}
// Reason is a string, or a nested list of conflicts.
type ConflictReasonMessage = string | Array<ConflictReason>;
// A field node and its definition in the parent-type context.
interface FieldDetails {
  parentType: Maybe<GraphQLNamedType>;
  node: FieldNode;
  definition: Maybe<GraphQLField<unknown, unknown>>;
}
type FieldDetailsList = Array<FieldDetails>;
type GroupedFieldSet = Map<string, FieldDetailsList>;
// Variable-map identity distinguishes fragment scopes in the caches.
type VariableMap = Map<string, ValueNode>;
interface FragmentSpread {
  key: string;
  node: FragmentSpreadNode;
  varMap: VariableMap | undefined;
}
type FragmentSpreads = ReadonlyArray<FragmentSpread>;
interface CollectFieldsResult {
  groupedFieldSet: GroupedFieldSet;
  fragmentSpreads: FragmentSpreads;
}
interface RuleContext {
  comparedFieldsAndFragmentPairs: OrderedPairSet<GroupedFieldSet, string>;
  comparedFragmentPairs: PairSet<string>;
  cachedCollectFieldsResults: Map<
    Maybe<GraphQLNamedType>,
    Map<SelectionSetNode, Map<VariableMap | undefined, CollectFieldsResult>>
  >;
}

/**
 * Find all conflicts found "within" a selection set, including those found
 * via spreading in fragments. Called when visiting each SelectionSet in the
 * GraphQL Document.
 *
 * Algorithm:
 *
 * Conflicts occur when two fields exist in a query which will produce the same
 * response name, but represent differing values, thus creating a conflict.
 * The algorithm below finds all conflicts via making a series of comparisons
 * between fields. In order to compare as few fields as possible, this makes
 * a series of comparisons "within" sets of fields and "between" sets of fields.
 *
 * Given any selection set, a collection produces both a set of fields by
 * also including all inline fragments, as well as a list of fragments
 * referenced by fragment spreads.
 *
 * A) Each selection set represented in the document first compares "within" its
 * collected set of fields, finding any conflicts between every pair of
 * overlapping fields.
 * Note: This is the *only time* that the fields "within" a set are compared
 * to each other. After this only fields "between" sets are compared.
 *
 * B) Also, if any fragment is referenced in a selection set, then a
 * comparison is made "between" the original set of fields and the
 * referenced fragment.
 *
 * C) Also, if multiple fragments are referenced, then comparisons
 * are made "between" each referenced fragment.
 *
 * D) When comparing "between" a set of fields and a referenced fragment, first
 * a comparison is made between each field in the original set of fields and
 * each field in the referenced set of fields.
 *
 * E) Also, if any fragment is referenced in the referenced selection set,
 * then a comparison is made "between" the original set of fields and the
 * referenced fragment (recursively referring to step D).
 *
 * F) When comparing "between" two fragments, first a comparison is made between
 * each field in the first referenced set of fields and each field in the
 * second referenced set of fields.
 *
 * G) Also, any fragments referenced by the first must be compared to the
 * second, and any fragments referenced by the second must be compared to the
 * first (recursively referring to step F).
 *
 * H) When comparing two fields, if both have selection sets, then a comparison
 * is made "between" both selection sets, first comparing the set of fields in
 * the first selection set with the set of fields in the second.
 *
 * I) Also, if any fragment is referenced in either selection set, then a
 * comparison is made "between" the other set of fields and the
 * referenced fragment.
 *
 * J) Also, if two fragments are referenced in both selection sets, then a
 * comparison is made "between" the two fragments.
 *
 * @internal
 */
function findConflictsWithinSelectionSet(
  validationContext: ValidationContext,
  ruleContext: RuleContext,
  parentType: Maybe<GraphQLNamedType>,
  selectionSet: SelectionSetNode,
  varMap: VariableMap | undefined,
): Array<Conflict> {
  const conflicts: Array<Conflict> = [];

  const { groupedFieldSet, fragmentSpreads } = collectFields(
    validationContext,
    ruleContext,
    parentType,
    selectionSet,
    varMap,
  );

  // (A) Find find all conflicts "within" the fields and f of this selection set.
  // Note: this is the *only place* `collectConflictsWithin` is called.
  collectConflictsWithin(
    validationContext,
    ruleContext,
    conflicts,
    groupedFieldSet,
    varMap,
  );

  if (fragmentSpreads.length !== 0) {
    // (B) Then collect conflicts between these fields and those represented by
    // each spread found.
    for (let i = 0; i < fragmentSpreads.length; i++) {
      collectConflictsBetweenFieldsAndFragment(
        validationContext,
        ruleContext,
        conflicts,
        false,
        groupedFieldSet,
        varMap,
        fragmentSpreads[i],
      );
      // (C) Then compare this fragment with all other fragments found in this
      // selection set to collect conflicts between fragments spread together.
      // This compares each item in the list of fragment spreads to every other
      // item in that same list (except for itself).
      for (let j = i + 1; j < fragmentSpreads.length; j++) {
        collectConflictsBetweenFragments(
          validationContext,
          ruleContext,
          conflicts,
          false,
          fragmentSpreads[i],
          fragmentSpreads[j],
        );
      }
    }
  }
  return conflicts;
}

// Collect all conflicts found between a set of fields and a fragment reference
// including via spreading in any nested fragments.
function collectConflictsBetweenFieldsAndFragment(
  validationContext: ValidationContext,
  ruleContext: RuleContext,
  conflicts: Array<Conflict>,
  areMutuallyExclusive: boolean,
  groupedFieldSet: GroupedFieldSet,
  varMap: VariableMap | undefined,
  fragmentSpread: FragmentSpread,
): void {
  if (groupedFieldSet.size === 0) {
    return;
  }

  const { comparedFieldsAndFragmentPairs } = ruleContext;
  // Memoize so the fields and fragments are not compared for conflicts more
  // than once.
  if (
    comparedFieldsAndFragmentPairs.has(
      groupedFieldSet,
      fragmentSpread.key,
      areMutuallyExclusive,
    )
  ) {
    return;
  }
  comparedFieldsAndFragmentPairs.add(
    groupedFieldSet,
    fragmentSpread.key,
    areMutuallyExclusive,
  );

  const fragment = validationContext.getFragment(
    fragmentSpread.node.name.value,
  );
  if (!fragment) {
    return;
  }

  const {
    groupedFieldSet: groupedFieldSet2,
    fragmentSpreads: referencedFragmentSpreads,
  } = collectFragmentFields(
    validationContext,
    ruleContext,
    fragment,
    fragmentSpread.varMap,
  );

  // Do not compare a fragment's groupedFieldSet to itself.
  if (groupedFieldSet === groupedFieldSet2) {
    return;
  }

  // (D) First collect any conflicts between the provided collection of fields
  // and the collection of fields represented by the given fragment.
  collectConflictsBetween(
    validationContext,
    ruleContext,
    conflicts,
    areMutuallyExclusive,
    groupedFieldSet,
    varMap,
    groupedFieldSet2,
    fragmentSpread.varMap,
  );

  // (E) Then collect any conflicts between the provided collection of fields
  // and any fragment names found in the given fragment.
  for (const referencedFragmentSpread of referencedFragmentSpreads) {
    collectConflictsBetweenFieldsAndFragment(
      validationContext,
      ruleContext,
      conflicts,
      areMutuallyExclusive,
      groupedFieldSet,
      varMap,
      referencedFragmentSpread,
    );
  }
}

// Collect all conflicts found between two fragments, including via spreading in
// any nested fragments.
function collectConflictsBetweenFragments(
  validationContext: ValidationContext,
  ruleContext: RuleContext,
  conflicts: Array<Conflict>,
  areMutuallyExclusive: boolean,
  fragmentSpread1: FragmentSpread,
  fragmentSpread2: FragmentSpread,
): void {
  const { comparedFragmentPairs } = ruleContext;
  // No need to compare a fragment to itself.
  if (fragmentSpread1.key === fragmentSpread2.key) {
    return;
  }

  if (fragmentSpread1.node.name.value === fragmentSpread2.node.name.value) {
    if (
      comparedFragmentPairs.has(fragmentSpread1.key, fragmentSpread2.key, false)
    ) {
      return;
    }
    comparedFragmentPairs.add(fragmentSpread1.key, fragmentSpread2.key, false);
    validationContext.reportError(
      new GraphQLError(
        `Spreads "${fragmentSpread1.node.name.value}" conflict because ${getFragmentSpreadDescription(fragmentSpread1.node)} and ${getFragmentSpreadDescription(fragmentSpread2.node)} have different fragment arguments.`,
        { nodes: [fragmentSpread1.node, fragmentSpread2.node] },
      ),
    );
    return;
  }

  // Memoize so two fragments are not compared for conflicts more than once.
  if (
    comparedFragmentPairs.has(
      fragmentSpread1.key,
      fragmentSpread2.key,
      areMutuallyExclusive,
    )
  ) {
    return;
  }
  comparedFragmentPairs.add(
    fragmentSpread1.key,
    fragmentSpread2.key,
    areMutuallyExclusive,
  );

  const fragment1 = validationContext.getFragment(
    fragmentSpread1.node.name.value,
  );
  const fragment2 = validationContext.getFragment(
    fragmentSpread2.node.name.value,
  );
  if (!fragment1 || !fragment2) {
    return;
  }

  const {
    groupedFieldSet: groupedFieldSet1,
    fragmentSpreads: referencedFragmentSpreads1,
  } = collectFragmentFields(
    validationContext,
    ruleContext,
    fragment1,
    fragmentSpread1.varMap,
  );
  const {
    groupedFieldSet: groupedFieldSet2,
    fragmentSpreads: referencedFragmentSpreads2,
  } = collectFragmentFields(
    validationContext,
    ruleContext,
    fragment2,
    fragmentSpread2.varMap,
  );

  // (F) First, collect all conflicts between these two collections of fields
  // (not including any nested fragments).
  collectConflictsBetween(
    validationContext,
    ruleContext,
    conflicts,
    areMutuallyExclusive,
    groupedFieldSet1,
    fragmentSpread1.varMap,
    groupedFieldSet2,
    fragmentSpread2.varMap,
  );

  // (G) Then collect conflicts between the first fragment and any nested
  // fragments spread in the second fragment.
  for (const referencedFragmentSpread2 of referencedFragmentSpreads2) {
    collectConflictsBetweenFragments(
      validationContext,
      ruleContext,
      conflicts,
      areMutuallyExclusive,
      fragmentSpread1,
      referencedFragmentSpread2,
    );
  }

  // (G) Then collect conflicts between the second fragment and any nested
  // fragments spread in the first fragment.
  for (const referencedFragmentSpread1 of referencedFragmentSpreads1) {
    collectConflictsBetweenFragments(
      validationContext,
      ruleContext,
      conflicts,
      areMutuallyExclusive,
      referencedFragmentSpread1,
      fragmentSpread2,
    );
  }
}

// Find all conflicts found between two selection sets, including those found
// via spreading in fragments. Called when determining if conflicts exist
// between the sub-fields of two overlapping fields.
function findConflictsBetweenSubSelectionSets(
  validationContext: ValidationContext,
  ruleContext: RuleContext,
  areMutuallyExclusive: boolean,
  parentType1: Maybe<GraphQLNamedType>,
  selectionSet1: SelectionSetNode,
  varMap1: VariableMap | undefined,
  parentType2: Maybe<GraphQLNamedType>,
  selectionSet2: SelectionSetNode,
  varMap2: VariableMap | undefined,
): Array<Conflict> {
  const conflicts: Array<Conflict> = [];

  const {
    groupedFieldSet: groupedFieldSet1,
    fragmentSpreads: fragmentSpreads1,
  } = collectFields(
    validationContext,
    ruleContext,
    parentType1,
    selectionSet1,
    varMap1,
  );
  const {
    groupedFieldSet: groupedFieldSet2,
    fragmentSpreads: fragmentSpreads2,
  } = collectFields(
    validationContext,
    ruleContext,
    parentType2,
    selectionSet2,
    varMap2,
  );

  // (H) First, collect all conflicts between these two collections of field.
  collectConflictsBetween(
    validationContext,
    ruleContext,
    conflicts,
    areMutuallyExclusive,
    groupedFieldSet1,
    varMap1,
    groupedFieldSet2,
    varMap2,
  );

  // (I) Then collect conflicts between the first collection of fields and
  // those referenced by each fragment name associated with the second.
  for (const fragmentSpread2 of fragmentSpreads2) {
    collectConflictsBetweenFieldsAndFragment(
      validationContext,
      ruleContext,
      conflicts,
      areMutuallyExclusive,
      groupedFieldSet1,
      varMap1,
      fragmentSpread2,
    );
  }

  // (I) Then collect conflicts between the second collection of fields and
  // those referenced by each fragment name associated with the first.
  for (const fragmentSpread1 of fragmentSpreads1) {
    collectConflictsBetweenFieldsAndFragment(
      validationContext,
      ruleContext,
      conflicts,
      areMutuallyExclusive,
      groupedFieldSet2,
      varMap2,
      fragmentSpread1,
    );
  }

  // (J) Also collect conflicts between any fragment spreads by the first and
  // fragment spreads by the second. This compares each item in the first set of
  // spreads to each item in the second set of spreads.
  for (const fragmentSpread1 of fragmentSpreads1) {
    for (const fragmentSpread2 of fragmentSpreads2) {
      collectConflictsBetweenFragments(
        validationContext,
        ruleContext,
        conflicts,
        areMutuallyExclusive,
        fragmentSpread1,
        fragmentSpread2,
      );
    }
  }
  return conflicts;
}

// Collect all Conflicts "within" one collection of fields.
function collectConflictsWithin(
  validationContext: ValidationContext,
  ruleContext: RuleContext,
  conflicts: Array<Conflict>,
  groupedFieldSet: GroupedFieldSet,
  varMap: VariableMap | undefined,
): void {
  // A field map is a keyed collection, where each key represents a response
  // name and the value at that key is a list of all fields which provide that
  // response name. For every response name, if there are multiple fields, they
  // must be compared to find a potential conflict.
  for (const [responseName, fieldDetailsList] of groupedFieldSet.entries()) {
    // This compares every field in the list to every other field in this list
    // (except to itself). If the list only has one item, nothing needs to
    // be compared.
    if (fieldDetailsList.length > 1) {
      for (let i = 0; i < fieldDetailsList.length; i++) {
        for (let j = i + 1; j < fieldDetailsList.length; j++) {
          const conflict = findConflict(
            validationContext,
            ruleContext,
            false, // within one collection is never mutually exclusive
            responseName,
            fieldDetailsList[i],
            varMap,
            fieldDetailsList[j],
            varMap,
          );
          if (conflict) {
            conflicts.push(conflict);
          }
        }
      }
    }
  }
}

// Collect all Conflicts between two collections of fields. This is similar to,
// but different from the `collectConflictsWithin` function above. This check
// assumes that `collectConflictsWithin` has already been called on each
// provided collection of fields. This is true because this validator traverses
// each individual selection set.
function collectConflictsBetween(
  validationContext: ValidationContext,
  ruleContext: RuleContext,
  conflicts: Array<Conflict>,
  parentFieldsAreMutuallyExclusive: boolean,
  groupedFieldSet1: GroupedFieldSet,
  varMap1: VariableMap | undefined,
  groupedFieldSet2: GroupedFieldSet,
  varMap2: VariableMap | undefined,
): void {
  if (groupedFieldSet1.size === 0 || groupedFieldSet2.size === 0) {
    return;
  }
  // A field map is a keyed collection, where each key represents a response
  // name and the value at that key is a list of all fields which provide that
  // response name. For any response name which appears in both provided field
  // maps, each field from the first field map must be compared to every field
  // in the second field map to find potential conflicts.
  for (const [responseName, fieldDetailsList1] of groupedFieldSet1.entries()) {
    const fieldDetailsList2 = groupedFieldSet2.get(responseName);
    if (fieldDetailsList2 != null) {
      for (const fieldDetails1 of fieldDetailsList1) {
        for (const fieldDetails2 of fieldDetailsList2) {
          const conflict = findConflict(
            validationContext,
            ruleContext,
            parentFieldsAreMutuallyExclusive,
            responseName,
            fieldDetails1,
            varMap1,
            fieldDetails2,
            varMap2,
          );
          if (conflict) {
            conflicts.push(conflict);
          }
        }
      }
    }
  }
}

// Determines if there is a conflict between two particular fields, including
// comparing their sub-fields.
function findConflict(
  validationContext: ValidationContext,
  ruleContext: RuleContext,
  parentFieldsAreMutuallyExclusive: boolean,
  responseName: string,
  fieldDetails1: FieldDetails,
  varMap1: VariableMap | undefined,
  fieldDetails2: FieldDetails,
  varMap2: VariableMap | undefined,
): Maybe<Conflict> {
  const {
    parentType: parentType1,
    node: node1,
    definition: def1,
  } = fieldDetails1;
  const {
    parentType: parentType2,
    node: node2,
    definition: def2,
  } = fieldDetails2;

  // If it is known that two fields could not possibly apply at the same
  // time, due to the parent types, then it is safe to permit them to diverge
  // in aliased field or arguments used as they will not present any ambiguity
  // by differing.
  // It is known that two parent types could never overlap if they are
  // different Object types. Interface or Union types might overlap - if not
  // in the current state of the schema, then perhaps in some future version,
  // thus may not safely diverge.
  const areMutuallyExclusive =
    parentFieldsAreMutuallyExclusive ||
    (parentType1 !== parentType2 &&
      isObjectType(parentType1) &&
      isObjectType(parentType2));

  if (!areMutuallyExclusive) {
    // Two aliases must refer to the same field.
    const name1 = node1.name.value;
    const name2 = node2.name.value;
    if (name1 !== name2) {
      return {
        responseName,
        reason: `"${name1}" and "${name2}" are different fields`,
        fields1: [node1],
        fields2: [node2],
      };
    }

    // Two field calls must have the same arguments.
    if (!sameArguments(node1.arguments, varMap1, node2.arguments, varMap2)) {
      return {
        responseName,
        reason: 'they have differing arguments',
        fields1: [node1],
        fields2: [node2],
      };
    }
  }

  const directives1 = node1.directives;
  const directives2 = node2.directives;
  const overlappingStreamReason = hasNoOverlappingStreams(
    directives1,
    varMap1,
    directives2,
    varMap2,
  );
  if (overlappingStreamReason !== undefined) {
    return {
      responseName,
      reason: overlappingStreamReason,
      fields1: [node1],
      fields2: [node2],
    };
  }

  // The return type for each field.
  const type1 = def1?.type;
  const type2 = def2?.type;

  if (type1 && type2 && doTypesConflict(type1, type2)) {
    return {
      responseName,
      reason: `they return conflicting types "${inspect(type1)}" and "${inspect(
        type2,
      )}"`,
      fields1: [node1],
      fields2: [node2],
    };
  }

  // Collect and compare sub-fields. Use the same "visited fragment spreads" list
  // for both collections so fields in a fragment reference are never
  // compared to themselves.
  const selectionSet1 = node1.selectionSet;
  const selectionSet2 = node2.selectionSet;
  if (selectionSet1 && selectionSet2) {
    const conflicts = findConflictsBetweenSubSelectionSets(
      validationContext,
      ruleContext,
      areMutuallyExclusive,
      getNamedType(type1),
      selectionSet1,
      varMap1,
      getNamedType(type2),
      selectionSet2,
      varMap2,
    );
    return subfieldConflicts(conflicts, responseName, node1, node2);
  }
}

function sameArguments<T extends ArgumentNode | FragmentArgumentNode>(
  args1: ReadonlyArray<T> | undefined,
  varMap1: VariableMap | undefined,
  args2: ReadonlyArray<T> | undefined,
  varMap2: VariableMap | undefined,
): boolean {
  if (args1 === undefined || args1.length === 0) {
    return args2 === undefined || args2.length === 0;
  }
  if (args2 === undefined || args2.length === 0) {
    return false;
  }

  if (args1.length !== args2.length) {
    return false;
  }

  const values2 = new Map(
    args2.map(({ name, value }) => [
      name.value,
      varMap2 === undefined ? value : replaceFragmentVariables(value, varMap2),
    ]),
  );
  return args1.every((arg1) => {
    let value1 = arg1.value;
    if (varMap1) {
      value1 = replaceFragmentVariables(value1, varMap1);
    }
    const value2 = values2.get(arg1.name.value);
    if (value2 === undefined) {
      return false;
    }

    return stringifyValue(value1) === stringifyValue(value2);
  });
}

function replaceFragmentVariables(
  valueNode: ValueNode,
  varMap: VariableMap,
): ValueNode {
  switch (valueNode.kind) {
    case Kind.VARIABLE:
      return varMap.get(valueNode.name.value) ?? valueNode;
    case Kind.LIST:
      return {
        ...valueNode,
        values: valueNode.values.map((node) =>
          replaceFragmentVariables(node, varMap),
        ),
      };
    case Kind.OBJECT:
      return {
        ...valueNode,
        fields: valueNode.fields.map((field) => ({
          ...field,
          value: replaceFragmentVariables(field.value, varMap),
        })),
      };
    default: {
      return valueNode;
    }
  }
}

function stringifyValue(value: ValueNode): string | null {
  return print(sortValueNode(value));
}

function getStreamDirective(
  directives: ReadonlyArray<DirectiveNode> | undefined,
): DirectiveNode | undefined {
  return directives?.find((directive) => directive.name.value === 'stream');
}

function hasNoOverlappingStreams(
  directives1: ReadonlyArray<DirectiveNode> | undefined,
  varMap1: VariableMap | undefined,
  directives2: ReadonlyArray<DirectiveNode> | undefined,
  varMap2: VariableMap | undefined,
): string | undefined {
  const stream1 = getStreamDirective(directives1);
  const stream2 = getStreamDirective(directives2);
  if (!stream1 && !stream2) {
    // both fields do not have streams
    return;
  } else if (stream1 && stream2) {
    // check if both fields have equivalent streams
    if (sameArguments(stream1.arguments, varMap1, stream2.arguments, varMap2)) {
      // This was allowed in previous alpha versions of `graphql-js`.
      return 'they have overlapping stream directives. See https://github.com/graphql/defer-stream-wg/discussions/100';
    }
    return 'they have overlapping stream directives';
  }
  // fields have a mix of stream and no stream
  return 'they have overlapping stream directives';
}

// Two types conflict if both types could not apply to a value simultaneously.
// Composite types are ignored as their individual field types will be compared
// later recursively. However List and Non-Null types must match.
function doTypesConflict(
  type1: GraphQLOutputType,
  type2: GraphQLOutputType,
): boolean {
  if (isListType(type1)) {
    return isListType(type2)
      ? doTypesConflict(type1.ofType, type2.ofType)
      : true;
  }
  if (isListType(type2)) {
    return true;
  }
  if (isNonNullType(type1)) {
    return isNonNullType(type2)
      ? doTypesConflict(type1.ofType, type2.ofType)
      : true;
  }
  if (isNonNullType(type2)) {
    return true;
  }
  if (isLeafType(type1) || isLeafType(type2)) {
    return type1 !== type2;
  }
  return false;
}

// Given a selection set, return the collection of fields (a mapping of response
// name to field nodes and definitions) as well as a list of fragment spreads
// referenced via fragment spreads.
function collectFields(
  validationContext: ValidationContext,
  ruleContext: RuleContext,
  parentType: Maybe<GraphQLNamedType>,
  selectionSet: SelectionSetNode,
  varMap: VariableMap | undefined,
): CollectFieldsResult {
  const { cachedCollectFieldsResults } = ruleContext;
  // A programmatically built document can share a selection-set object between
  // different parent types; their field definitions must not share a cache entry.
  let bySelectionSet = cachedCollectFieldsResults.get(parentType);
  if (!bySelectionSet) {
    bySelectionSet = new Map();
    cachedCollectFieldsResults.set(parentType, bySelectionSet);
  }
  let cache = bySelectionSet.get(selectionSet);
  if (!cache) {
    cache = new Map();
    bySelectionSet.set(selectionSet, cache);
  }
  const cached = cache.get(varMap);
  if (cached) {
    return cached;
  }
  const groupedFieldSet: GroupedFieldSet = new Map();
  const fragmentSpreads = new Map<string, FragmentSpread>();
  collectFieldsImpl(
    validationContext,
    parentType,
    selectionSet,
    groupedFieldSet,
    fragmentSpreads,
    varMap,
  );
  const collectFieldsResult: CollectFieldsResult = {
    groupedFieldSet,
    fragmentSpreads: Array.from(fragmentSpreads.values()),
  };
  cache.set(varMap, collectFieldsResult);
  return collectFieldsResult;
}

// Given a reference to a fragment, return the represented collection of fields
// as well as a list of nested fragment spreads referenced via fragment spreads.
function collectFragmentFields(
  validationContext: ValidationContext,
  ruleContext: RuleContext,
  fragment: FragmentDefinitionNode,
  varMap: VariableMap | undefined,
) {
  const fragmentType = typeFromAST(
    validationContext.getSchema(),
    fragment.typeCondition,
  );
  return collectFields(
    validationContext,
    ruleContext,
    fragmentType,
    fragment.selectionSet,
    varMap,
  );
}

function collectFieldsImpl(
  validationContext: ValidationContext,
  parentType: Maybe<GraphQLNamedType>,
  selectionSet: SelectionSetNode,
  groupedFieldSet: GroupedFieldSet,
  fragmentSpreads: Map<string, FragmentSpread>,
  varMap: VariableMap | undefined,
): void {
  for (const selection of selectionSet.selections) {
    switch (selection.kind) {
      case Kind.FIELD: {
        const fieldName = selection.name.value;
        let fieldDef;
        if (isObjectType(parentType) || isInterfaceType(parentType)) {
          fieldDef = parentType.getFields()[fieldName];
        }
        const responseName = selection.alias
          ? selection.alias.value
          : fieldName;

        let fieldDetailsList = groupedFieldSet.get(responseName);
        if (fieldDetailsList == null) {
          fieldDetailsList = [];
          groupedFieldSet.set(responseName, fieldDetailsList);
        }
        fieldDetailsList.push({
          parentType,
          node: selection,
          definition: fieldDef,
        });
        break;
      }
      case Kind.FRAGMENT_SPREAD: {
        const fragmentSpread = getFragmentSpread(
          validationContext,
          selection,
          varMap,
        );
        fragmentSpreads.set(fragmentSpread.key, fragmentSpread);
        break;
      }
      case Kind.INLINE_FRAGMENT: {
        const typeCondition = selection.typeCondition;
        const inlineFragmentType = typeCondition
          ? typeFromAST(validationContext.getSchema(), typeCondition)
          : parentType;
        collectFieldsImpl(
          validationContext,
          inlineFragmentType,
          selection.selectionSet,
          groupedFieldSet,
          fragmentSpreads,
          varMap,
        );
        break;
      }
    }
  }
}

function getFragmentSpread(
  validationContext: ValidationContext,
  fragmentSpreadNode: FragmentSpreadNode,
  varMap: VariableMap | undefined,
): FragmentSpread {
  let key = '';
  const fragmentSignature = validationContext.getFragmentSignatureByName()(
    fragmentSpreadNode.name.value,
  );
  const argMap = new Map<string, ValueNode>();
  if (fragmentSpreadNode.arguments) {
    for (const arg of fragmentSpreadNode.arguments) {
      argMap.set(arg.name.value, arg.value);
    }
  }
  if (fragmentSignature?.variableDefinitions) {
    key += fragmentSpreadNode.name.value + '(';
    for (const varName of fragmentSignature.variableDefinitions.keys()) {
      const value = argMap.get(varName);
      if (value) {
        const scopedValue = varMap
          ? replaceFragmentVariables(value, varMap)
          : value;
        key += varName + ': ' + stringifyValue(scopedValue);
      }
    }
    key += ')';
  }
  return {
    key,
    node: fragmentSpreadNode,
    varMap: getVarMap(fragmentSignature, key),
  };
}

function getVarMap(
  fragmentSignature: ReturnType<ValidationContext['getFragmentSignature']>,
  key = '',
): VariableMap | undefined {
  if (!fragmentSignature || fragmentSignature.variableDefinitions.size === 0) {
    return;
  }
  const varMap = new Map<string, ValueNode>();
  for (const variableName of fragmentSignature.variableDefinitions.keys()) {
    varMap.set(variableName, {
      kind: Kind.VARIABLE,
      name: { kind: Kind.NAME, value: JSON.stringify([key, variableName]) },
    });
  }
  return varMap;
}

function getFragmentSpreadDescription(node: FragmentSpreadNode): string {
  return print({ ...node, directives: [] }).slice(3);
}

// Given a series of Conflicts which occurred between two sub-fields, generate
// a single Conflict.
function subfieldConflicts(
  conflicts: ReadonlyArray<Conflict>,
  responseName: string,
  node1: FieldNode,
  node2: FieldNode,
): Maybe<Conflict> {
  if (conflicts.length > 0) {
    return {
      responseName,
      reason: conflicts.map(({ responseName: name, reason }) => ({
        responseName: name,
        reason,
      })),
      fields1: [node1, ...conflicts.map(({ fields1 }) => fields1).flat()],
      fields2: [node2, ...conflicts.map(({ fields2 }) => fields2).flat()],
    };
  }
}

/**
 * A way to keep track of pairs of things where the ordering of the pair
 * matters.
 *
 * Provides a third argument for has/set to allow flagging the pair as
 * weakly or strongly present within the collection.
 *
 * @internal
 */
class OrderedPairSet<T, U> {
  _data: Map<T, Map<U, boolean>>;

  constructor() {
    this._data = new Map();
  }

  has(a: T, b: U, weaklyPresent: boolean): boolean {
    const result = this._data.get(a)?.get(b);
    if (result === undefined) {
      return false;
    }

    return weaklyPresent ? true : weaklyPresent === result;
  }

  add(a: T, b: U, weaklyPresent: boolean): void {
    const map = this._data.get(a);
    if (map === undefined) {
      this._data.set(a, new Map([[b, weaklyPresent]]));
    } else {
      map.set(b, weaklyPresent);
    }
  }
}

/**
 * A way to keep track of pairs of similar things when the ordering of the pair
 * does not matter.
 *
 * @internal
 */
class PairSet<T> {
  _orderedPairSet: OrderedPairSet<T, T>;

  constructor() {
    this._orderedPairSet = new OrderedPairSet();
  }

  has(a: T, b: T, weaklyPresent: boolean): boolean {
    return (
      this._orderedPairSet.has(a, b, weaklyPresent) ||
      this._orderedPairSet.has(b, a, weaklyPresent)
    );
  }

  add(a: T, b: T, weaklyPresent: boolean): void {
    this._orderedPairSet.add(a, b, weaklyPresent);
  }
}
